                              ${isActive 
                                ? 'bg-neon/10 text-neon border border-neon/20' 
                                : 'text-slate-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-slate-800 hover:text-slate-900 dark:hover:text-white border border-transparent'
