          {/* Theme Toggle Button (Sidebar Bottom) */}
          <div className="p-4 border-t border-gray-100 dark:border-slate-800 shrink-0">
             <button 
               onClick={onToggleTheme}
               className="w-full flex items-center justify-between p-3 rounded-xl bg-gray-50 dark:bg-slate-800 hover:bg-gray-100 dark:hover:bg-slate-700 transition-colors group"
             >
                <div className="flex items-center gap-3 text-slate-700 dark:text-slate-300">
                  {isDarkMode ? <Moon size={18} className="text-neon" /> : <Sun size={18} className="text-amber-500" />}
                  <span className="text-sm font-semibold">{isDarkMode ? 'Dark Mode' : 'Light Mode'}</span>
                </div>
                <div className={`w-10 h-6 rounded-full relative transition-colors duration-300 ${isDarkMode ? 'bg-neon' : 'bg-gray-300'}`}>
                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-transform duration-300 ${isDarkMode ? 'translate-x-5' : 'translate-x-1'}`}></div>
                </div>
             </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default Sidebar;

import React, { useRef } from 'react';
import { X, ImagePlus, Sparkles } from 'lucide-react';
import { AspectRatio, UploadedImage } from '../types';

interface InputPanelProps {
  uploadedImages: UploadedImage[];
  onUpload: (files: File[]) => void;
  onRemoveImage: (id: string) => void;
  prompt: string;
  setPrompt: (val: string) => void;
  aspectRatio: AspectRatio;
  setAspectRatio: (val: AspectRatio) => void;
  onGenerate: () => void;
  isGenerating: boolean;
}

const InputPanel: React.FC<InputPanelProps> = ({
  uploadedImages,
  onUpload,
  onRemoveImage,
  prompt,
  setPrompt,
  aspectRatio,
  setAspectRatio,
  onGenerate,
  isGenerating,
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onUpload(Array.from(e.target.files));
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const triggerUpload = () => fileInputRef.current?.click();

  const ratios = [
    { value: AspectRatio.SQUARE, label: 'Square (1:1)', icon: 'w-6 h-6 border-2 border-current rounded-sm' },
    { value: AspectRatio.WIDE, label: 'Wide (16:9)', icon: 'w-8 h-5 border-2 border-current rounded-sm' },
    { value: AspectRatio.PORTRAIT, label: 'Portrait (9:16)', icon: 'w-5 h-8 border-2 border-current rounded-sm' },
  ];

  const isButtonDisabled = isGenerating || uploadedImages.length === 0 || !prompt.trim();

  return (
    <div className="flex flex-col w-full bg-white dark:bg-slate-900 transition-colors">
      <div className="h-16 flex items-center px-6 border-b border-gray-100 dark:border-slate-800 shrink-0 sticky top-0 bg-white dark:bg-slate-900 z-10">
        <h2 className="font-semibold text-lg text-slate-800 dark:text-white">Konfigurasi Penggabungan</h2>
      </div>

      {/* Area Input yang bisa di-scroll secara keseluruhan */}
      <div className="p-6 space-y-8">

        {/* Section 1: Upload */}
        <div className="space-y-3">
          <div className="flex justify-between items-center">
            <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Upload Foto</label>
            <span className="text-xs text-slate-400">{uploadedImages.length}/5 Foto</span>
          </div>

          <div className="grid grid-cols-3 gap-3">
            {uploadedImages.map((img) => (
              <div key={img.id} className="relative group aspect-square rounded-xl overflow-hidden border border-gray-200 dark:border-slate-700 shadow-sm">
                <img src={img.previewUrl} alt="upload" className="w-full h-full object-cover" />
                <button 
                  onClick={() => onRemoveImage(img.id)}
                  className="absolute top-1.5 right-1.5 p-1.5 bg-black/60 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity backdrop-blur-sm"
                >
                  <X size={12} />
                </button>
              </div>
            ))}

            {uploadedImages.length < 5 && (
              <button 
                onClick={triggerUpload}
                className="aspect-square rounded-xl border-2 border-dashed border-gray-200 dark:border-slate-700 flex flex-col items-center justify-center text-slate-400 hover:border-neon hover:text-neon transition-all bg-gray-50 dark:bg-slate-800/50 hover:bg-neon-light dark:hover:bg-neon/5"
              >
                <ImagePlus size={24} />
                <span className="text-xs mt-2 font-medium">Tambah</span>
              </button>
            )}
          </div>
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            className="hidden" 
            accept="image/*" 
            multiple
          />
        </div>

        {/* Section 2: Prompt */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Prompt / Instruksi</label>
          <div className="relative">
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              placeholder="Contoh: Gabungkan produk sepatu ini dengan latar belakang pegunungan bersalju yang epik, pencahayaan dramatis..."
              className="w-full h-32 p-4 rounded-xl border border-gray-200 dark:border-slate-700 text-sm focus:outline-none focus:ring-2 focus:ring-neon focus:border-transparent resize-none bg-gray-50 dark:bg-slate-800/50 dark:text-slate-200 transition-colors"
            />
            <div className="absolute bottom-3 right-3 text-slate-400">
              <Sparkles size={16} />
            </div>
          </div>
        </div>

        {/* Section 3: Ratio */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Aspek Rasio</label>
          <div className="grid grid-cols-3 gap-3">
            {ratios.map((r) => (
              <button
                key={r.value}
                onClick={() => setAspectRatio(r.value)}
                className={`flex flex-col items-center justify-center py-4 px-2 rounded-xl border transition-all ${
                  aspectRatio === r.value 
                    ? 'border-neon bg-neon-light dark:bg-emerald-950/30 text-neon shadow-sm' 
                    : 'border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-400 hover:border-gray-300 dark:hover:border-slate-600 hover:text-slate-600 dark:hover:text-slate-300'
                }`}
              >
                <div className={r.icon}></div>
                <span className="text-[11px] mt-2 font-bold whitespace-nowrap">{r.label}</span>
              </button>
            ))}
          </div>
        </div>

        {/* Section 4: Generate Button (Sekarang di dalam scroll area) */}
        <div className="pt-4 pb-12">
          <button
            onClick={onGenerate}
            disabled={isButtonDisabled}
            className={`w-full py-4 rounded-xl flex items-center justify-center gap-2 font-bold text-white transition-all shadow-lg shadow-neon/20 active:scale-[0.98] ${
              isButtonDisabled
                ? 'bg-gray-200 dark:bg-slate-800 text-slate-400 dark:text-slate-600 cursor-not-allowed shadow-none border border-transparent'
                : 'bg-neon hover:bg-neon-hover border border-neon hover:border-neon-hover'
            }`}
          >
            {isGenerating ? (
              <>
                <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                <span>Sedang Memproses...</span>
              </>
            ) : (
              <>
                <Sparkles size={20} />
                <span>Generate Fusion</span>
              </>
            )}
          </button>

          {uploadedImages.length === 0 && (
            <p className="text-[10px] text-center text-slate-400 mt-3 font-medium">
              *Upload minimal 1 foto untuk mulai menggabungkan.
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default InputPanel;

import React, { useRef } from 'react';
import { Upload, X, ImagePlus, Sparkles, History } from 'lucide-react';
import { AspectRatio, UploadedImage } from '../types';

interface RestorePanelProps {
  image: UploadedImage | null;
  onUpload: (file: File) => void;
  onRemove: () => void;
  aspectRatio: AspectRatio;
  setAspectRatio: (val: AspectRatio) => void;
  onGenerate: () => void;
  isGenerating: boolean;
}

const RestorePanel: React.FC<RestorePanelProps> = ({
  image,
  onUpload,
  onRemove,
  aspectRatio,
  setAspectRatio,
  onGenerate,
  isGenerating,
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      onUpload(e.target.files[0]);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const triggerUpload = () => fileInputRef.current?.click();

  const ratios = [
    { value: AspectRatio.SQUARE, label: 'Square (1:1)', icon: 'w-6 h-6 border-2 border-current rounded-sm' },
    { value: AspectRatio.WIDE, label: 'Wide (16:9)', icon: 'w-8 h-5 border-2 border-current rounded-sm' },
    { value: AspectRatio.PORTRAIT, label: 'Portrait (9:16)', icon: 'w-5 h-8 border-2 border-current rounded-sm' },
  ];

  return (
    <div className="flex-1 h-full bg-white dark:bg-slate-900 flex flex-col min-w-0 border-r border-gray-200 dark:border-slate-800 transition-colors">
      <div className="h-16 flex items-center px-6 border-b border-gray-100 dark:border-slate-800 shrink-0">
        <h2 className="font-semibold text-lg text-slate-800 dark:text-white">Restorasi Foto</h2>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar">

        {/* Section 1: Upload */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Upload Foto Jadul</label>

          <div className="w-full">
            {image ? (
              <div className="relative group rounded-xl overflow-hidden border border-gray-200 dark:border-slate-700 bg-gray-50 dark:bg-slate-800">
                <img src={image.previewUrl} alt="upload" className="w-full h-auto max-h-[300px] object-contain" />
                <button 
                  onClick={onRemove}
                  className="absolute top-2 right-2 p-2 bg-black/50 text-white rounded-full hover:bg-neon transition-colors"
                >
                  <X size={16} />
                </button>
              </div>
            ) : (
              <button 
                onClick={triggerUpload}
                className="w-full h-48 rounded-xl border-2 border-dashed border-gray-300 dark:border-slate-700 flex flex-col items-center justify-center text-slate-400 hover:border-neon hover:text-neon transition-colors bg-gray-50 dark:bg-slate-800"
              >
                <div className="p-3 bg-white dark:bg-slate-700 rounded-full mb-3 shadow-sm">
                   <History size={32} />
                </div>
                <span className="font-medium">Pilih Foto</span>
                <span className="text-xs mt-1 text-slate-400">JPG, PNG</span>
              </button>
            )}
          </div>
          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            className="hidden" 
            accept="image/*" 
          />
        </div>

        {/* Section 2: Info */}
        <div className="p-4 bg-neon-light dark:bg-emerald-900/20 border border-emerald-100 dark:border-emerald-900/30 rounded-xl">
           <h3 className="text-sm font-semibold text-neon mb-1">Fitur Restorasi</h3>
           <ul className="text-xs text-slate-600 dark:text-slate-400 list-disc list-inside space-y-1">
             <li>Memperbaiki goresan dan noda</li>
             <li>Menjernihkan foto buram</li>
             <li>Mewarnai foto hitam putih</li>
             <li>Meningkatkan resolusi</li>
           </ul>
        </div>

        {/* Section 3: Ratio */}
        <div className="space-y-3">
          <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Aspek Rasio Output</label>
          <div className="grid grid-cols-3 gap-3">
            {ratios.map((r) => (
              <button
                key={r.value}
                onClick={() => setAspectRatio(r.value)}
                className={`flex flex-col items-center justify-center p-4 rounded-xl border transition-all ${
                  aspectRatio === r.value 
                    ? 'border-neon bg-neon-light dark:bg-emerald-950/30 text-neon' 
                    : 'border-gray-200 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-400 hover:border-gray-300 dark:hover:border-slate-600'
                }`}
              >
                <div className={r.icon}></div>
                <span className="text-xs mt-2 font-medium">{r.label}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="p-6 border-t border-gray-100 dark:border-slate-800 bg-white dark:bg-slate-900 sticky bottom-0 z-10">
        <button
          onClick={onGenerate}
          disabled={isGenerating || !image}
          className={`w-full py-4 rounded-xl flex items-center justify-center gap-2 font-semibold text-white transition-all shadow-lg shadow-neon/20 ${
            isGenerating || !image
              ? 'bg-gray-300 dark:bg-slate-700 cursor-not-allowed shadow-none'
              : 'bg-neon hover:bg-neon-hover'
