        >
          {isGenerating ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
              <span>Sedang Merestorasi...</span>
            </>
          ) : (
            <>
              <Sparkles size={20} />
              <span>Restorasi Foto</span>
            </>
          )}
        </button>
      </div>
    </div>
  );
