                            >
                                {age === 'child' ? 'Anak' : age === 'adult' ? 'Dewasa' : 'Custom'}
                            </button>
                        ))}
                    </div>
                    {ageGroup === 'custom' && (
                         <input 
                            type="text" 
                            value={customAge}
                            onChange={(e) => setCustomAge(e.target.value)}
